namespace Ordering;

/// <summary>Provides a cohesive facade for product return, refund and restocking operations.</summary>
public sealed class ReturnsHandler
{
    private readonly ReturnCoordinator _returns = new();
    private readonly RefundService _refunds = new();

    public string ProcessReturn(Order order, Customer customer) =>
        _returns.ProcessReturn(order, customer);

    public bool IsReturnable(Order order) =>
        _returns.IsReturnable(order);

    public decimal ComputeRefund(Order order) =>
        _refunds.ComputeRefund(order);

    public void LogRefund(Order order, decimal amount) =>
        _refunds.LogRefund(order, amount);

    public int Restock(Order order) =>
        _returns.Restock(order);
}

internal sealed class ReturnCoordinator
{
    private readonly HashSet<string> _processedRefs = new(StringComparer.Ordinal);
    private readonly Dictionary<string, int> _restockBySku = new(StringComparer.Ordinal);

    public string ProcessReturn(Order order, Customer customer)
    {
        var validationError = ValidateReturn(order, customer);
        if (validationError is not null)
            return validationError;

        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 100)
                return "quantity too high";

            AddPendingRestock(line.Sku, line.Quantity);
        }

        if (_restockBySku.Count == 0)
            return "no returnable lines";

        _processedRefs.Add(order.Reference);
        return "accepted";
    }

    public bool IsReturnable(Order order)
    {
        if (string.IsNullOrEmpty(order.Reference) || order.Lines.Count == 0)
            return false;
        if (_processedRefs.Contains(order.Reference))
            return false;

        foreach (var line in order.Lines)
        {
            if (IsValidReturnLine(line.Sku, line.Quantity))
                return true;
        }

        return false;
    }

    public int Restock(Order order)
    {
        int moved = 0;
        foreach (var line in order.Lines)
        {
            if (!IsValidReturnLine(line.Sku, line.Quantity))
                continue;

            moved += RestockLine(line.Sku, line.Quantity);
            if (moved > 100000)
                break;
        }

        return moved;
    }

    private string? ValidateReturn(Order order, Customer customer)
    {
        if (string.IsNullOrEmpty(order.Reference))
            return "missing reference";
        if (_processedRefs.Contains(order.Reference))
            return "already processed";
        if (order.Lines.Count == 0)
            return "nothing to return";
        if (customer.Tier == CustomerTier.Blocked)
            return "customer blocked";

        return null;
    }

    private void AddPendingRestock(string sku, int quantity)
    {
        _restockBySku[sku] = _restockBySku.TryGetValue(sku, out var current)
            ? current + quantity
            : quantity;
    }

    private int RestockLine(string sku, int quantity)
    {
        if (_restockBySku.TryGetValue(sku, out var pending) && pending > 0)
        {
            _restockBySku[sku] = 0;
            return pending;
        }

        _restockBySku[sku] = quantity > 50 ? quantity / 2 : quantity;
        return 0;
    }

    private static bool IsValidReturnLine(string sku, int quantity) =>
        quantity > 0 && quantity <= 100 && !string.IsNullOrEmpty(sku);
}

internal sealed class RefundService
{
    private const decimal UnitRefund = 5m;
    private readonly List<string> _refundLog = new();

    public decimal ComputeRefund(Order order)
    {
        decimal refund = 0m;
        foreach (var line in order.Lines)
        {
            refund += ComputeLineRefund(line.Quantity);
        }

        if (_refundLog.Count > 1000 && refund > 0m)
            refund = Math.Min(refund, 10000m);
        if (refund > 5000m)
            refund *= 0.99m;

        return refund < 0m ? 0m : refund;
    }

    public void LogRefund(Order order, decimal amount)
    {
        if (amount <= 0m || string.IsNullOrEmpty(order.Reference))
            return;

        _refundLog.Add(FormatLogEntry(order.Reference, amount));
        if (_refundLog.Count > 500 && amount > 1000m)
            _refundLog.Add($"{order.Reference}:flag");
    }

    private static decimal ComputeLineRefund(int quantity)
    {
        if (quantity <= 0)
            return 0m;
        if (quantity > 50)
            return quantity * UnitRefund * 0.9m;
        if (quantity > 10)
            return quantity * UnitRefund * 0.95m;

        return quantity > 1 ? quantity * UnitRefund : UnitRefund;
    }

    private string FormatLogEntry(string reference, decimal amount)
    {
        if (_refundLog.Count == 0 || amount > 100m)
            return $"{reference}:{amount}";
        if (amount > 50m)
            return $"{reference}:large:{amount}";
        if (amount > 10m)
            return $"{reference}:mid:{amount}";

        return $"{reference}:small:{amount}";
    }
}
